export function clamp(value        , low        , high        )         {
  return Math.max(low, Math.min(high, value));
}

// Wheel speeds for one of the four drive buttons. Turning spins on the spot: a faster right
// wheel turns the rover left, as in the protocol.
export function driveFor(direction           , speed        )         {
  const s = clamp(speed, 0, 1);
  switch (direction) {
    case "forward":
      return { left: s, right: s };
    case "back":
      return { left: -s, right: -s };
    case "left":
      return { left: -s, right: s };
    case "right":
      return { left: s, right: -s };
  }
}

export function keyDirection(key        )                   {
  switch (key.toLowerCase()) {
    case "w":
    case "arrowup":
      return "forward";
    case "s":
    case "arrowdown":
      return "back";
    case "a":
    case "arrowleft":
      return "left";
    case "d":
    case "arrowright":
      return "right";
    default:
      return null;
  }
}

const HEADLINES                         = {
  scanning: "Looking at the scene.",
  need_survivor: "Find the survivor.",
  plan_ready: "Check the plan, then approve it.",
  blocked: "There is no safe way through.",
  clear: "The way is already clear.",
  waiting: "Waiting for the rover.",
  running: "The rover is clearing the way.",
  verifying: "Checking the result.",
  aborted: "The run was stopped.",
};

const FALLBACK_HEADLINE = "Looking at the scene.";

export function headlineFor(phase        , verified                )         {
  if (phase === "done") {
    return verified ? "The way is clear." : "The rover finished, but it is not confirmed.";
  }
  return HEADLINES[phase] ?? FALLBACK_HEADLINE;
}

// What to tell the person when the laptop cannot reach the rover, or null when it can.
export function roverNotice(connected         , address        , error        )                {
  if (connected) return null;
  const detail = error ? ` (${error})` : "";
  return `Not connected to the rover at ${address}. Nothing can be sent until it is.${detail}`;
}

const WARN_PHASES = ["blocked", "aborted", "need_survivor"];

export function toneFor(phase        , linkUp         , verified                , cameraError               )       {
  if (verified === true) return "ok";
  if (WARN_PHASES.includes(phase) || !linkUp || cameraError || verified === false) return "warn";
  return "";
}

export const BUSY_PHASES = ["waiting", "running", "verifying"];
export const END_PHASES = ["done", "aborted"];

// A click or tap on the picture, as a position in the camera's own pixels.
export function toFrame(clientX        , clientY        , box     , frame                          ) {
  return {
    x: ((clientX - box.left) * frame.w) / box.width,
    y: ((clientY - box.top) * frame.h) / box.height,
  };
}

// Where a marker laid over a picture shown at a different size belongs, in CSS pixels.
export function toDisplay(point                  , boxWidth        , frameWidth        ) {
  const scale = boxWidth / frameWidth;
  return { left: point[0] * scale, top: point[1] * scale };
}
